import{z as i,x as l,o as A,c as s,q as e,j as t,D as a,d as B,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"硬件与执行","description":"","frontmatter":{"title":"硬件与执行","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-hardware.md","filePath":"quant/ex-hardware.md","lastUpdated":1791063341000}'),p={name:"quant/ex-hardware.md"};function d(h,E,c,u,m,C){const r=l("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="硬件与执行" tabindex="-1">硬件与执行 <a class="header-anchor" href="#硬件与执行" aria-label="Permalink to &quot;硬件与执行&quot;">​</a></h1><div class="epigraph"><p>执行栈的延迟不是竞赛成绩，是预算表：每个算法按状态更新周期领取毫秒与微秒；超预算的后果不是慢，是决策用了过期的状态。</p><footer>—— 据 Budish, Cramton and Shim, The High-Frequency Trading Arms Race, Quarterly Journal of Economics, 2015；交易系统实务整理</footer></div><p><a href="/quant/ex-tca-deep-pitfalls">上一课</a>的结论是度量分辨率受时间戳与时钟同步限制；镜头再往里推一层就是执行栈本身。主干 <a href="/quant/colocation-microwave">主机托管与微波</a>写了物理层，<a href="/quant/latency-budget">延迟预算</a>写了通用分解；本课从执行算法的视角写硬件：哪些环节要预算、多少、可靠性为何比速度重要。A 股托管受公平接入约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>执行算法是状态机：状态来自行情事件，动作用于订单事件。状态过期，决策就错——用上一拍的 BBO 决定是否吃簿，可能在价格移走后把单送进薄簿；中点 peg 的重挂延迟，让暗池里挂着按旧中点成交的单。延迟的执行学定义是：<strong>事件发生到动作生效之间，状态变化未被计入的概率</strong>。可靠性更硬：重复下单、丢单、且回执，任何一次都是事故。问题是怎么给流水线分配预算并让故障有界。</p><p><span class="marginnote">「延迟的执行学定义是状态过期概率」翻译成小白话：快不快不是重点，重点是做决定那一刻手里的行情是否已经过时。延迟 10 毫秒但期间市场没动，等于零延迟；延迟 1 毫秒却恰逢价格跳变，就是拿着旧地图开车。延迟的价值取决于状态变没变，不是秒表读数。</span></p><h3 id="预算分配与算法类型挂钩" tabindex="-1">预算分配与算法类型挂钩 <a class="header-anchor" href="#预算分配与算法类型挂钩" aria-label="Permalink to &quot;预算分配与算法类型挂钩&quot;">​</a></h3><p>预算跟着算法的状态更新周期走。跑几小时的 VWAP 日程，决策周期是秒到分钟，几百毫秒的栈延迟无关紧要；流动性寻求类算法要抢盘口事件先行权，毫秒级；排队敏感的 maker 执行要微秒级。把 FPGA 与内核旁路（见 <a href="/quant/low-latency-engineering">低延迟工程：内核旁路与 FPGA</a>）装到不需要它的算法上是错配。分解沿用 <a href="/quant/latency-budget">延迟预算</a> 的口径：行情解析、策略、风控、网关、线路，每段设 p99 目标——尾延迟才是丢队位的来源。</p><p><span class="marginnote">评估延迟改善要用算法语言：maker 执行的期望损失近似为「队位丢失概率 × 半价差节省」。延迟从 5 毫秒降到 1 毫秒，只在丢队位概率对延迟敏感的标的与时段有价值；平静的大盘股上收益常常不到十分之一基点。</span></p>',9)),(A(),t(o,null,{default:a(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALG%5B%22%E6%89%A7%E8%A1%8C%E7%AE%97%E6%B3%95%E6%8C%89%E7%8A%B6%E6%80%81%E6%9B%B4%E6%96%B0%E5%91%A8%E6%9C%9F%E9%A2%86%E9%A2%84%E7%AE%97%22%5D%20--%3E%20V%5B%22VWAP%20%E6%97%A5%E7%A8%8B%E5%9E%8B%EF%BC%9A%E5%86%B3%E7%AD%96%E5%91%A8%E6%9C%9F%E7%A7%92%E5%88%B0%E5%88%86%E9%92%9F%22%5D%0A%20%20ALG%20--%3E%20L%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E5%AF%BB%E6%B1%82%E5%9E%8B%EF%BC%9A%E6%8A%A2%E7%9B%98%E5%8F%A3%E4%BA%8B%E4%BB%B6%E5%85%88%E8%A1%8C%E6%9D%83%22%5D%0A%20%20ALG%20--%3E%20M%5B%22%E6%8E%92%E9%98%9F%E6%95%8F%E6%84%9F%20maker%20%E5%9E%8B%EF%BC%9A%E9%98%9F%E4%BD%8D%E5%B0%B1%E6%98%AF%E9%92%B1%22%5D%0A%20%20V%20--%3E%20V1%5B%22%E9%A2%84%E7%AE%97%EF%BC%9A%E5%87%A0%E7%99%BE%E6%AF%AB%E7%A7%92%E8%B6%B3%E5%A4%9F%EF%BC%8CFPGA%20%E6%98%AF%E9%94%99%E9%85%8D%22%5D%0A%20%20L%20--%3E%20L1%5B%22%E9%A2%84%E7%AE%97%EF%BC%9A%E6%AF%AB%E7%A7%92%E7%BA%A7%E6%A0%88%22%5D%0A%20%20M%20--%3E%20M1%5B%22%E9%A2%84%E7%AE%97%EF%BC%9A%E5%BE%AE%E7%A7%92%E7%BA%A7%EF%BC%8C%E7%9C%8B%20p99%20%E5%B0%BE%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20V1%20--%3E%20S%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9A%E9%A2%84%E7%AE%97%E8%8A%B1%E5%9C%A8%E7%8A%B6%E6%80%81%E6%9C%80%E5%AE%B9%E6%98%93%E8%BF%87%E6%9C%9F%E7%9A%84%E7%8E%AF%E8%8A%82%22%5D%0A%20%20L1%20--%3E%20S%0A%20%20M1%20--%3E%20S%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>可靠性设计先于提速。订单状态机单写者、全量序号，回执与订单一一挂账；定时对账 drop copy，未确认订单限时重查；断线即撤与速率上限是交易所侧的最后防线；杀单开关按母单、账户两级预设。行情侧：解析与业务逻辑分离，坏包丢弃并计数。时钟：全网 PTP 同步，打点统一到网关出口，保证 <a href="/quant/tca">成交后分析 TCA</a> 时间戳可比。测试：延迟回归进 CI，用录制行情与回执回放，报告 p50/p99/p999。</p><p><span class="marginnote">数字感受为什么盯 p99 不看平均：一天 10 万笔子单，p99 意味着最慢的 1000 笔走慢路径——排队敏感策略的队位丢失就发生在这 1% 上，平均值再漂亮也救不回这些单。恐慌日的尾延迟往往比平时差一个数量级，容量要按峰值流量设计。</span></p><p>预算的经济学：把预算花在「状态最容易过期」的段——通常是行情解析与网关排队。队列堆积的丢包与乱序比稳态延迟更伤，按恐慌日峰值流量设计。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟转化为成本的核心机制是逆向选择：你反应慢，先看到信息的人已经动了价格，被动单被挑走或主动单吃在旧价上；<a href="/quant/latency-arbitrage">延迟套利</a> 描述的正是把他人延迟变成利润的一侧。执行端关心镜像：延迟让执行算法站在被挑走的一边。Budish 等人把速度军备竞赛写成对高频信息的租金竞争，执行算法不必参赛，但必须知道自己交了多少「过时税」。可靠性机制则是尾部：重复下单的损失是库存错误量级，风控检查段不可裁剪——那是把尾部从执行账搬进风险账。</p><p>A 股的制度层压缩了速度竞争：<a href="/quant/cn-colocation-rectify">托管清退与整改</a>后，公平接入是硬约束，参数空间里没有「用微秒换利润」的维度，工程重点是稳定性、报备与撤单率可控，见 <a href="/quant/cn-fee-cancel-ratio">差异化收费与撤单率监控</a>。</p>',7)),(A(),t(o,null,{default:a(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEED%5B%22%E8%A1%8C%E6%83%85%E6%8A%A5%E6%96%87%22%5D%20--%3E%20PARSE%5B%22%E8%A7%A3%E6%9E%90%E4%B8%8E%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20PARSE%20--%3E%20STRAT%5B%22%E7%AE%97%E6%B3%95%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20STRAT%20--%3E%20RISK%5B%22%E9%A3%8E%E6%8E%A7%E6%A3%80%E6%9F%A5%3A%20%E9%99%90%E9%A2%9D%20%2F%20%E8%87%AA%E6%88%90%E4%BA%A4%22%5D%0A%20%20RISK%20--%3E%20GW%5B%22%E8%AE%A2%E5%8D%95%E7%BD%91%E5%85%B3%22%5D%0A%20%20GW%20--%3E%20EX%5B%22%E4%BA%A4%E6%98%93%E6%89%80%22%5D%0A%20%20EX%20--%3E%20ACK%5B%22%E5%9B%9E%E6%89%A7%E4%B8%8E%E6%88%90%E4%BA%A4%22%5D%0A%20%20ACK%20--%3E%20LEDGER%5B%22%E6%8C%82%E8%B4%A6%E5%AF%B9%E8%B4%A6%20%2F%20drop%20copy%22%5D%0A%20%20LEDGER%20--%3E%20STRAT%0A%20%20CLK%5B%22PTP%20%E6%97%B6%E9%92%9F%22%5D%20--%3E%20TS%5B%22%E4%BA%8B%E4%BB%B6%E6%89%93%E7%82%B9%22%5D%0A%20%20TS%20--%3E%20TCA%5B%22TCA%20%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>延迟测量只在生产上有意义：回放的栈延迟与生产的热身状态、中断聚合、队列竞争不同，跨环境比较要声明条件。收益估计依赖队位模型，模型错则方向错。不要把硬件升级当执行质量的替代：日程、路由、价格保护做错，提速只是更快地执行错误。合规是硬边界：报备的接口与撤单率约束限制高频改单能力，A 股尤其如此。成本核算：托管与专用硬件是固定成本，说不清回报的延迟投资按治理规则否决。</p><p><span class="marginnote">常见误区：以为硬件升级能补救执行策略的缺陷。日程切错时段、路由漏了更优场所、价格保护没设围栏——这些错误提速后只会以更高频率重复。先让决策在慢速环境下被验证正确，再把预算花在状态过期最贵的环节。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>延迟的执行学定义是状态过期概率：预算按状态更新周期分配，看 p99 不看均值。</li><li>VWAP 日程要秒级，流动性寻求要毫秒级，排队敏感要微秒级；错配是浪费或事故。</li><li>可靠性先于速度：单写者状态机、drop copy 对账、断线即撤、杀单开关是底线。</li><li>延迟转化为成本的机制是被逆向选择的一侧；风控检查段不可裁剪。</li><li>A 股公平接入约束压缩了速度竞争，工程重点转向稳定与合规。</li><li>出处：Budish, Cramton and Shim, <em>QJE</em>, 2015；延迟预算与低延迟工程见主干对应课程。</li></ul>',5))])}const D=i(p,[["render",d]]);export{F as __pageData,D as default};
